mapper.select:
select

from FIN_FLOAT_ACCRUAL_SCHE
where CASH_ID = #{cashId,jdbcType=VARCHAR}
and ACCR_DATE = #{accrDate,jdbcType=DATE}

mapper.delete:
delete from FIN_FLOAT_ACCRUAL_SCHE
where CASH_ID = #{cashId,jdbcType=VARCHAR}
  and ACCR_DATE = #{accrDate,jdbcType=DATE}

mapper.update:
update FIN_FLOAT_ACCRUAL_SCHE
set ACCR_STR_DATE = #{accrStrDate,jdbcType=DATE},
    ACCR_END_DATE = #{accrEndDate,jdbcType=DATE},
    VAL_DATE = #{valDate,jdbcType=DATE},
    UPDATE_USER = #{updateUser,jdbcType=VARCHAR},
    UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP}
where CASH_ID = #{cashId,jdbcType=VARCHAR}
  and ACCR_DATE = #{accrDate,jdbcType=DATE}
